1	<?php
2	/**
3	 * Hromadne akce s objednavkami (formular ze seznamu objednavek).
4	 *
5	 * POST ids[] + action:
6	 *   storno   – stornuje vybrane objednavky
7	 *   paid     – oznaci jako zaplacene (parovani plateb z banky, 2016)
8	 *   shipped  – oznaci jako odeslane (hromadne odeslani balíku)
9	 */
10	
11	global $db;
12	legacy_db();
13	auth_require('obchod');
14	csrf_check();
15	
16	$ids = isset($_POST['ids']) ? $_POST['ids'] : array();
17	$action = isset($_POST['action']) ? (string) $_POST['action'] : '';
18	
19	if (!is_array($ids) || count($ids) == 0) {
20	    flash('Nevybrali jste žádné objednávky', 'error');
21	    redirect(admin_url('orders'));
22	    return;
23	}
24	
25	$idList = ids_to_sql($ids);
26	
27	if ($action == 'storno') {
28	    // stornovat lze cokoliv krome dorucenych (2017: i odeslane, kdyz se balik vrati)
29	    $before = $db->query("SELECT id, status FROM orders WHERE id IN (" . $idList . ")");
30	    $n = $db->exec("UPDATE orders SET status = 'cancelled' WHERE id IN (" . $idList . ") AND status != 'delivered'");
31	    foreach ($before as $b) {
32	        if ($b['status'] != 'delivered') {
33	            audit_log('order', $b['id'], 'storno', array('from' => $b['status'], 'bulk' => true));
34	        }
35	    }
36	    // FIXME: rezervace ve skladu zustanou viset, viz StockReport::orphanReservations()
37	    flash('Stornováno objednávek: ' . $n);
38	} elseif ($action == 'paid') {
39	    $n = $db->exec("UPDATE orders SET status = 'paid' WHERE id IN (" . $idList . ") AND status = 'confirmed'");
40	    foreach ($ids as $oid) {
41	        audit_log('order', $oid, 'status', array('to' => 'paid', 'bulk' => true));
42	    }
43	    flash('Označeno jako zaplacené: ' . $n);
44	} elseif ($action == 'shipped') {
45	    $n = $db->exec("UPDATE orders SET status = 'shipped' WHERE id IN (" . $idList . ") AND status = 'paid'");
46	    foreach ($ids as $oid) {
47	        audit_log('order', $oid, 'status', array('to' => 'shipped', 'bulk' => true));
48	    }
49	    flash('Označeno jako odeslané: ' . $n);
50	} else {
51	    flash('Neznámá akce', 'error');
52	}
53	
54	cache_delete('dashboard_stats');
55	redirect(admin_url('orders'));
