1	<?php
2	/**
3	 * Uprava objednavky – zmena stavu a slevy.
4	 *
5	 * ?id=<uuid>
6	 *
7	 * Puvodne (2015) se tu dalo upravovat vsechno vcetne polozek, od 2024
8	 * objednavky zaklada novy e-shop, takze tu zustal jen stav a sleva.
9	 * Obchodaci to pouzivaji, kdyz zakaznik zaplati prevodem a nic se nesparuje.
10	 */
11	
12	global $db;
13	legacy_db();
14	auth_require('obchod');
15	
16	$id = get_param('id');
17	if ($id == '') {
18	    $id = post_param('id');
19	}
20	
21	$order = $db->one("SELECT * FROM orders WHERE id = '" . $id . "'");
22	if ($order === null) {
23	    echo '<p class="err">Objednávka nenalezena.</p>';
24	    return;
25	}
26	
27	$errors = array();
28	$msg = '';
29	
30	if (is_post()) {
31	    csrf_check();
32	    $newStatus = post_param('status');
33	    $discount = post_param('discount');
34	
35	    // --- zmena stavu ---
36	    if ($newStatus != '' && $newStatus != $order['status']) {
37	        if (!isset($GLOBALS['ORDER_STATES'][$newStatus])) {
38	            $errors[] = 'Neplatný stav';
39	        } else {
40	            // obchodaci obcas vraceji stornovane zpet – zakazano (2016, po incidentu)
41	            if ($order['status'] == 'cancelled' && !auth_has_role('admin')) {
42	                $errors[] = 'Stornovanou objednávku může obnovit jen admin';
43	            } else {
44	                $db->exec("UPDATE orders SET status = '" . $newStatus . "' WHERE id = '" . $id . "'");
45	
46	                // pri potvrzeni doplnit datum, pokud chybi (stare objednavky)
47	                if ($newStatus == 'confirmed' && $order['placed_at'] === null) {
48	                    $db->exec("UPDATE orders SET placed_at = '" . date('Y-m-d H:i:s') . "' WHERE id = '" . $id . "'");
49	                }
50	
51	                audit_log('order', $id, 'status', array('from' => $order['status'], 'to' => $newStatus));
52	
53	                // mail zakaznikovi pri odeslani
54	                if ($newStatus == 'shipped') {
55	                    $c = $db->one("SELECT email FROM customers WHERE id = '" . $order['customer_id'] . "'");
56	                    if ($c) {
57	                        send_mail($c['email'], 'Vaše objednávka byla odeslána', "Dobrý den,\n\nvaše objednávka " . $id . " byla právě odeslána.\n");
58	                    }
59	                }
60	                // TODO: pri 'cancelled' uvolnit rezervace ve skladu (cron to taky nedela)
61	                $msg .= 'Stav změněn na ' . order_state_label($newStatus) . '. ';
62	            }
63	        }
64	    }
65	
66	    // --- sleva ---
67	    if ($discount !== '') {
68	        $discountCents = kc2hal($discount);
69	        if ($discountCents < 0) {
70	            $errors[] = 'Sleva nemůže být záporná';
71	        } elseif ($discountCents != (int) $order['discount_amount_in_cents']) {
72	            $sum = order_total($id);
73	            if ($discountCents > $sum) {
74	                // sleva vetsi nez objednavka – povolime, ale upozornime (pozadavek obchodu 2017)
75	                $msg .= 'Pozor: sleva je vyšší než hodnota objednávky! ';
76	            }
77	            $db->exec("UPDATE orders SET discount_amount_in_cents = " . $discountCents . ", discount_currency = '" . $order['currency'] . "' WHERE id = '" . $id . "'");
78	            audit_log('order', $id, 'discount', array('from' => (int) $order['discount_amount_in_cents'], 'to' => $discountCents));
79	            $msg .= 'Sleva uložena. ';
80	        }
81	    }
82	
83	    // poznamka k uprave
84	    $note = post_param('note');
85	    if ($note != '') {
86	        $db->exec("INSERT INTO order_notes (order_id, author, note, created_at) VALUES ('" . $id . "', '" . auth_login_name() . "', " . $db->quote($note) . ", '" . date('Y-m-d H:i:s') . "')");
87	    }
88	
89	    cache_delete('dashboard_stats');
90	
91	    // znovu nacist
92	    $order = $db->one("SELECT * FROM orders WHERE id = '" . $id . "'");
93	}
94	
95	$items = $db->query("SELECT i.*, p.name FROM order_items i LEFT JOIN products p ON p.id = i.product_id WHERE i.order_id = '" . $id . "'");
96	$sum = order_total($id);
97	
98	$pageTitle = 'Úprava objednávky';
99	include LEGACY_TEMPLATES . '/partials/old_header.php';
100	?>
101	<h1>Úprava objednávky <?php echo h($order['id']); ?></h1>
102	
103	<?php if ($msg != '') { ?><p class="msg"><?php echo h($msg); ?></p><?php } ?>
104	<?php foreach ($errors as $e) { ?><p class="err"><?php echo h($e); ?></p><?php } ?>
105	
106	<form method="post"><?php echo csrf_field(); ?>
107	<input type="hidden" name="id" value="<?php echo h($order['id']); ?>">
108	<table class="grid" style="width:auto">
109	    <tr><th>Zákazník</th><td><?php echo h(customer_name($order['customer_id'])); ?></td></tr>
110	    <tr><th>Datum</th><td><?php echo format_date($order['placed_at'], true); ?></td></tr>
111	    <tr><th>Stav</th><td>
112	        <select name="status">
113	        <?php foreach ($GLOBALS['ORDER_STATES'] as $k => $v) { ?>
114	            <option value="<?php echo h($k); ?>"<?php echo $k == $order['status'] ? ' selected' : ''; ?>><?php echo h($v); ?></option>
115	        <?php } ?>
116	        </select>
117	    </td></tr>
118	    <tr><th>Hodnota položek</th><td><?php echo format_price($sum, $order['currency']); ?></td></tr>
119	    <tr><th>Sleva (<?php echo h($order['currency']); ?>)</th><td><input type="text" name="discount" value="<?php echo h(number_format(((int) $order['discount_amount_in_cents']) / 100, 2, ',', '')); ?>" size="10"></td></tr>
120	    <tr><th>Poznámka</th><td><textarea name="note" rows="3" cols="50"></textarea></td></tr>
121	</table>
122	<p><input type="submit" value="Uložit"></p>
123	</form>
124	
125	<h2>Položky</h2>
126	<table class="grid">
127	<?php foreach ($items as $it) { ?>
128	    <tr>
129	        <td><?php echo h($it['name'] !== null ? $it['name'] : $it['product_id']); ?></td>
130	        <td class="num"><?php echo (int) $it['quantity']; ?> ks</td>
131	        <td class="num"><?php echo format_price($it['unit_price_amount_in_cents'], $it['unit_price_currency']); ?></td>
132	    </tr>
133	<?php } ?>
134	</table>
135	<p><a href="<?php echo h(admin_url('order', array('id' => $order['id']))); ?>">« detail objednávky</a></p>
136	<?php
137	include LEGACY_TEMPLATES . '/partials/old_footer.php';
