2	/**
3	 * Prehled objednavek pro stats.php a dashboard.
4	 * (jana.k 2017 – "objektove", ale data jsou porad v poli)
5	 */
6	
7	namespace App\Legacy\lib;
8	
9	class OrderReport
10	{
11	    public $from;
12	
13	    public $to;
14	
15	    public $rows = array();
16	
17	    public function __construct($from = null, $to = null)
18	    {
19	        $this->from = $from !== null ? $from : date('Y-m-01');
20	        $this->to = $to !== null ? $to : date('Y-m-d');
21	    }
22	
23	    public function load()
24	    {
25	        global $db;
26	        legacy_db();
27	        $sql = "SELECT o.*, (SELECT SUM(quantity * unit_price_amount_in_cents) FROM order_items WHERE order_id = o.id) AS total"
28	            . " FROM orders o WHERE o.placed_at >= '" . $this->from . " 00:00:00'"
29	            . " AND o.placed_at <= '" . $this->to . " 23:59:59'"
30	            . " ORDER BY o.placed_at DESC";
31	        $this->rows = $db->query($sql);
32	
33	        return $this;
34	    }
35	
36	    public function countByState()
37	    {
38	        $out = array();
39	        foreach ($this->rows as $r) {
40	            if (!isset($out[$r['status']])) {
41	                $out[$r['status']] = 0;
42	            }
43	            $out[$r['status']]++;
44	        }
45	
46	        return $out;
47	    }
48	
49	    /**
50	     * Soucet za obdobi – v CZK podle PriceUtils kurzu (ne exchange_rates!),
51	     * vcetne vsech stavu krome stornovanych.
52	     */
53	    public function total()
54	    {
55	        $sum = 0;
56	        foreach ($this->rows as $r) {
57	            if ($r['status'] == 'cancelled' || $r['status'] == 'draft') {
58	                continue;
59	            }
60	            $sum += PriceUtils::toCzk((int) $r['total'], $r['currency']);
61	        }
62	
63	        return $sum;
64	    }
65	
66	    public function averageOrder()
67	    {
68	        $n = 0;
69	        foreach ($this->rows as $r) {
70	            if ($r['status'] != 'cancelled' && $r['status'] != 'draft') {
71	                $n++;
72	            }
73	        }
74	        if ($n == 0) {
75	            return 0;
76	        }
77	
78	        return (int) round($this->total() / $n);
79	    }
80	
81	    /**
82	     * Po dnech pro graf: 'YYYY-MM-DD' => pocet
83	     */
84	    public function perDay()
85	    {
86	        $out = array();
87	        foreach ($this->rows as $r) {
88	            if ($r['placed_at'] === null) {
89	                continue;
90	            }
91	            $d = substr($r['placed_at'], 0, 10);
92	            if (!isset($out[$d])) {
93	                $out[$d] = 0;
94	            }
95	            $out[$d]++;
96	        }
97	        ksort($out);
98	
99	        return $out;
100	    }
101	
102	    public function cancelledRatio()
103	    {
104	        $c = $this->countByState();
105	        $all = count($this->rows);
106	        if ($all == 0) {
107	            return 0;
108	        }
109	
110	        return round((isset($c['cancelled']) ? $c['cancelled'] : 0) / $all * 100, 1);
111	    }
112	}
